         and exists (select 1 from role_tasks where role = 'sales' and task = 'cancel.ask')) then 'in: step 3 puts it in again, changing nothing' else 'not in: step 3 puts it in' end)
) as t(n, m, state) order by n;

-- a) The new Sales app places its orders through place_order (0180): one
--    write, numbered by the server, placed once however often a phone on
--    bad signal sends it. The server writes who took it, nothing paid, and,
--    on credit, the shop's Credit charge (and its chase-after days when
--    Sales names none). The old sales.html still places orders as before.
--    Who places (quote.make), and the Credit charge each order will carry:
select s.name as shop, a.presets ->> 'creditPct' as credit_charge_pct, a.presets ->> 'chaseAfterDays' as credit_days_when_none_named,
       (select string_agg(r.role, ', ' order by r.role) from role_tasks r where r.task = 'quote.make') as who_places
  from app_settings a join shops s on s.id = a.shop_id order by s.name;

-- b) Sales can ask the Manager to cancel an order (0181; the new task
--    cancel.ask, the new table cancel_asks): only their own order, before
--    it is invoiced or delivered. The Manager is pushed "Cancel asked" and
--    answers yes (the order is cancelled, as by Cancel) or no, with words,
--    and the salesperson is pushed the answer. Who asks, and who answers:
select m.role, coalesce(nullif(btrim(m.display_name), ''), '(no name)') as person,
       case when m.role = 'sales' then 'asks to cancel' else 'answers the ask' end as part
  from shop_members m
 where m.role = 'sales' or m.role in (select r.role from role_tasks r where r.task = 'order.cancel')
 order by 3, 1, 2;

-- c) Yard workers (staff logins) no longer read the cash book, customers'
--    debts, supplier bills, payroll or the owner's log, and hold the yard's
--    own tasks: pick, load, deliver (0179). The worker app reads none of
--    those tables, so they see no change. Where 0179 is in already, step 3
--    changes nothing for them.
select coalesce(nullif(btrim(m.display_name), ''), '(no name)') as yard_worker,
       case when (to_regprocedure('ow_yard_worker(uuid)') is not null
         and (select count(distinct polrelid) from pg_policy where polname = 'not a yard worker') >= 21
         and (select count(*) from role_tasks where role = 'staff' and task in ('order.pick', 'order.load', 'order.deliver')) = 3) then 'kept out already (0179 is in)' else 'kept out after step 3' end as the_books
  from shop_members m where m.role = 'staff' order by 1;

