-- 0179 Yard workers keep out of the books (docs/spec/05-data.md §8 Q1 and
-- Q2, Kevin 28 Oct 2026).
--
-- 0164 kept a Store login to the yard's own functions (ow_yard_only), so it
-- reads no money. A yard worker logs in as 'staff' (invite-worker), and
-- ow_yard_only names 'store' alone: a staff login could read every table a
-- member can -- the cash book, every customer's debt, the supplier bills,
-- payroll, the owner's log. Checked on 28 Oct: a staff login read
-- cash_txns and customers; a Store login read none.
--
-- The worker app (worker.html, left as it is while the rebuild goes on)
-- reads and writes orders, trips, products, suppliers, staff, agents and
-- the settings directly, so 'staff' cannot be shut out the way 'store' is
-- without breaking it. Instead:
--
--   1. A staff login is refused the money and customer tables the worker
--      app never reads (a restrictive "not a yard worker" policy, every
--      operation): cash_txns, cash_days, customers, customer_debt_log,
--      purchase_invoices, dues, loans, fixed_assets, rent_agreements,
--      supplier_commissions, decision_log, payment_asks, invoice_asks,
--      payment_promises, statements_sent, agent_commission_claims,
--      shop_payment_providers, fresh_starts, manager_notes, briefs_sent,
--      login_sessions. The server's own functions and triggers run as the
--      database and are not affected; the three order triggers that run as
--      the caller touch none of these tables.
--   2. 'staff' holds the yard's tasks -- order.pick, order.load,
--      order.deliver -- as docs/decision-rights.md now says, so the rule
--      lives in role_tasks and not in role names written into functions
--      (0164's store_patch_order, 0178).
--
-- Not closed here: an order's prices and payments, which the worker app
-- reads in saved_quotes. That needs the worker app to read through a
-- stripped function, as the Store does (0164 ow_store_payload).
--
-- Applied by hand, after 0178. Safe to run twice.
--
-- CHECK AFTERWARDS:
--   select count(*) from pg_policy where polname = 'not a yard worker';   -- 21
--   select task from role_tasks where role = 'staff' order by 1;          -- order.deliver, order.load, order.pick
--
-- ROLLBACK:
--   do $r$ declare t text; begin
--     foreach t in array array['cash_txns','cash_days','customers','customer_debt_log','purchase_invoices','dues','loans','fixed_assets',
--       'rent_agreements','supplier_commissions','decision_log','payment_asks','invoice_asks','payment_promises','statements_sent',
--       'agent_commission_claims','shop_payment_providers','fresh_starts','manager_notes','briefs_sent','login_sessions'] loop
--       execute format('drop policy if exists "not a yard worker" on %I', t);
--     end loop; end $r$;
--   drop function if exists ow_yard_worker(uuid);
--   delete from role_tasks where role = 'staff' and task in ('order.pick', 'order.load', 'order.deliver');
-- ---------------------------------------------------------------------

-- Whether the caller is a yard worker (a staff login) in this shop.
create or replace function ow_yard_worker(p_shop uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from shop_members m where m.shop_id = p_shop and m.user_id = auth.uid() and m.role = 'staff');
$$;
revoke all on function ow_yard_worker(uuid) from public, anon;
grant execute on function ow_yard_worker(uuid) to authenticated;

do $mig$
declare t text;
begin
  foreach t in array array['cash_txns', 'cash_days', 'customers', 'customer_debt_log', 'purchase_invoices', 'dues', 'loans', 'fixed_assets',
    'rent_agreements', 'supplier_commissions', 'decision_log', 'payment_asks', 'invoice_asks', 'payment_promises', 'statements_sent',
    'agent_commission_claims', 'shop_payment_providers', 'fresh_starts', 'manager_notes', 'briefs_sent', 'login_sessions'] loop
    execute format('drop policy if exists "not a yard worker" on %I', t);
    execute format('create policy "not a yard worker" on %I as restrictive for all to authenticated '
                   'using (not ow_yard_worker(shop_id)) with check (not ow_yard_worker(shop_id))', t);
  end loop;
end $mig$;

insert into role_tasks (role, task) values ('staff', 'order.pick'), ('staff', 'order.load'), ('staff', 'order.deliver') on conflict do nothing;
$m0179$;
end $apply0179$;

-- ---------------------------------------------------------------------
-- 0180_place_order.sql
-- ---------------------------------------------------------------------
-- 0180 Sales places an order through a server function (docs/spec/05-data.md
-- §8 Q3 and §9 Q6, Kevin 28 Oct 2026: the new apps write orders only
-- through server functions; docs/rebuild.md).
--
-- Until now Sales placed an order with two calls from the phone: an id from
-- next_row_id_blocks('row:saved_quote') (0138), then a direct insert into
-- saved_quotes (sales.html slide:place, 8718-8738; src/core/supabase/write.ts
-- copied it). A phone that lost signal between the two, or sent the insert
-- twice, left a gap or an order entered twice (the canvas's OR19). Now:
--
--   place_order(shop, row, key)
--       quote.make (Sales; the owner and admins hold every task). One
--       write: the order is numbered from row:saved_quote and inserted as
--       sales.html inserts it -- the same columns, the same payload
--       (client, items, charges, credit, savedAt, createdAt, payments [],
--       customerId, debtCharged 0, stageEnteredAt, stageLog, takenBy) --
--       so every guard and trigger on saved_quotes fires as it did on the
--       phone's insert, as the caller: 0119's gate (a shelf-only order to
--       Packing, a held move kept as gateHeldMove), 0165's money check,
--       0167's test-record mark (qa), 0171's no sale under cost (OWCST),
--       0173's stage rule (Packing needs quote.make or order.move), 0174's
--       gate reasons, 0175's checks on the Manager's answers, and the
--       pushes (0120's price.waits, credit.hold).
--
--       From the phone it takes only what Sales decides: the client's name
--       and phone, the lines, the charges, on credit or not (and the days),
--       the customer, where it goes (deliverTo), the chat it came from
--       (waConvId), and where it starts ('draft' Checking, or 'preparing'
--       Packing when all of it is on our shelf). The rest is the server's:
--       the number, the date (ow_today), the times, who took it (the
--       caller), nothing paid, and the Credit charge's pct, which is the
--       shop's (presets.creditPct, as sales.html nwQuoteOf writes it), so
--       no phone sells on credit without it.
--
--       Placed once: a key (the phone's draft key) sent again answers with
--       the order it already placed ('again': true), so a retry after lost
--       signal never makes a copy. Without a key every call places one, as
--       the insert did.
--
--       Refused: no login or not a member, no quote.make (42501); nothing
--       to place, a start other than Checking or Packing (22023); a
--       customer not in this shop's books (P0002); and whatever the guards
--       refuse.
--
--       Returns {ok, id, number ('#0558'), status (where it stands after
--       the gate), again}.
--
-- The direct insert is not closed here: sales.html (frozen) and the console
-- still place orders that way. Q3 closes it for each role when its old app
-- retires.
--
-- Applied by hand, after 0179. Safe to run twice.
--
-- CHECK AFTERWARDS:
--   select pg_get_function_identity_arguments('place_order'::regproc);   -- p_shop_id uuid, p_row jsonb, p_key text
--   select id, client_name, status, payload ->> 'takenBy', payload ->> 'placeKey' from saved_quotes order by id desc limit 5;
--
-- ROLLBACK:
--   drop function if exists place_order(uuid, jsonb, text);
--   drop index if exists saved_quotes_place_key_idx;
-- ---------------------------------------------------------------------

-- A key is looked up per shop; only orders placed with one carry it.
create index if not exists saved_quotes_place_key_idx on saved_quotes (shop_id, (payload ->> 'placeKey')) where payload ? 'placeKey';

create or replace function place_order(p_shop_id uuid, p_row jsonb, p_key text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  v_key text := nullif(left(regexp_replace(btrim(coalesce(p_key, '')), '[^A-Za-z0-9._:-]', '', 'g'), 80), '');
  src jsonb;
  presets jsonb;
  v_status text;
  items jsonb;
  charges jsonb;
  credit jsonb := null;
  days numeric;
  cid text;
  c customers%rowtype;
  v_name text;
  v_phone text;
  p jsonb;
  floor_id bigint;
  new_id bigint;
  got saved_quotes%rowtype;
  now_ms bigint := (extract(epoch from now()) * 1000)::bigint;
  now_iso text := to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
begin
  if uid is null or not is_shop_member(p_shop_id) then
    raise exception 'Sign in to this shop first.' using errcode = '42501';
  end if;
  if not has_task(p_shop_id, 'quote.make') then
    raise exception 'Taking an order is Sales'' (quote.make).' using errcode = '42501';
  end if;
  if jsonb_typeof(p_row) is distinct from 'object' or jsonb_typeof(p_row -> 'payload') is distinct from 'object' then
    raise exception 'Nothing to place.' using errcode = '22023';
  end if;

  -- Placed once: the same key again is the order it placed.
  if v_key is not null then
    perform pg_advisory_xact_lock(hashtextextended(p_shop_id::text || ':place_order:' || v_key, 0));
    select * into got from saved_quotes
     where shop_id = p_shop_id and payload ? 'placeKey' and payload ->> 'placeKey' = v_key
     order by id limit 1;
    if found then
      return jsonb_build_object('ok', true, 'id', got.id, 'number', '#' || lpad(got.id::text, 4, '0'), 'status', got.status, 'again', true);
    end if;
  end if;

  src := p_row -> 'payload';
  v_status := coalesce(nullif(btrim(coalesce(p_row ->> 'status', '')), ''), 'draft');
  if v_status not in ('draft', 'preparing') then
    raise exception 'A new order starts in Checking or Packing.' using errcode = '22023';
  end if;
  items := case when jsonb_typeof(src -> 'items') = 'array' then src -> 'items' else '[]'::jsonb end;
  if jsonb_array_length(items) = 0 then raise exception 'Add an item to place.' using errcode = '22023'; end if;
  if exists (select 1 from jsonb_array_elements(items) e where jsonb_typeof(e) <> 'object') then
    raise exception 'Each line is an item.' using errcode = '22023';
  end if;
  charges := case when jsonb_typeof(src -> 'charges') = 'array' then src -> 'charges' else '[]'::jsonb end;
  if exists (select 1 from jsonb_array_elements(charges) e where jsonb_typeof(e) <> 'object') then
    raise exception 'Each charge is a line of its own.' using errcode = '22023';
  end if;

  -- The customer: one in this shop's books, or none (a walk-in).
  cid := nullif(btrim(coalesce(src ->> 'customerId', '')), '');
  if cid is not null then
    select * into c from customers where shop_id = p_shop_id and id = cid;
    if not found then raise exception 'That customer is not in the books.' using errcode = 'P0002'; end if;
  end if;
  v_name := coalesce(nullif(btrim(coalesce(p_row ->> 'client_name', '')), ''), nullif(btrim(coalesce(src -> 'client' ->> 'name', '')), ''),
                     nullif(btrim(coalesce(c.name, '')), ''), 'Walk-in');
  v_phone := nullif(btrim(coalesce(p_row ->> 'client_phone', src -> 'client' ->> 'phone', '')), '');

  -- On credit: the shop's Credit charge (presets.creditPct), for the days asked (else presets.chaseAfterDays).
  if jsonb_typeof(src -> 'credit') = 'object' then
    presets := coalesce((select a.presets from app_settings a where a.shop_id = p_shop_id), '{}'::jsonb);
    days := ow_num(src -> 'credit' ->> 'days');
    if days is null or days < 0 then days := greatest(0, coalesce(ow_num(presets ->> 'chaseAfterDays'), 0)); end if;
    credit := jsonb_build_object('pct', greatest(0, coalesce(ow_num(presets ->> 'creditPct'), 0)), 'days', round(days), 'agreedAt', ow_today());
  end if;

  p := jsonb_build_object(
         'client', jsonb_build_object('name', v_name, 'phone', coalesce(v_phone, '')),
         'items', items, 'charges', charges, 'credit', credit,
         'savedAt', now_iso, 'createdAt', now_iso, 'payments', '[]'::jsonb, 'customerId', cid, 'debtCharged', 0,
         'stageEnteredAt', now_ms, 'stageLog', jsonb_build_array(jsonb_build_object('status', v_status, 'at', now_ms)),
         'takenBy', uid::text);
  if jsonb_typeof(src -> 'deliverTo') = 'string' and btrim(src ->> 'deliverTo') <> '' then
    p := p || jsonb_build_object('deliverTo', left(btrim(src ->> 'deliverTo'), 200));
  end if;
  if jsonb_typeof(src -> 'waConvId') = 'number' then p := p || jsonb_build_object('waConvId', src -> 'waConvId'); end if;
  if v_key is not null then p := p || jsonb_build_object('placeKey', v_key); end if;

  -- The number, then the order: an ordinary insert, so every guard and trigger judges it as the caller.
  select coalesce(max(id), 0) into floor_id from saved_quotes;  -- ids are one sequence across shops (0001)
  new_id := ow_next_row_id(p_shop_id, 'row:saved_quote', floor_id);
  insert into saved_quotes (id, shop_id, client_name, client_phone, date, status, invoiced, invoiced_at, invoiced_ts, amount_paid, voided, payload)
       values (new_id, p_shop_id, v_name, v_phone, ow_today(), v_status, false, null, null, 0, false, p)
  returning * into got;

  return jsonb_build_object('ok', true, 'id', got.id, 'number', '#' || lpad(got.id::text, 4, '0'), 'status', got.status, 'again', false);
end $$;
revoke all on function place_order(uuid, jsonb, text) from public, anon;
grant execute on function place_order(uuid, jsonb, text) to authenticated;

-- ---------------------------------------------------------------------
-- 0181_sales_cancel_ask.sql
-- ---------------------------------------------------------------------
-- 0181 Sales asks the Manager to cancel an order (docs/spec/01-order-journey.md
-- §5 Q7; docs/spec/05-data.md §9 Q7; the canvas's OR18 "Ask Ruth to cancel",
-- OR19 "Entered twice · cancel the copy"). 0177 gave the Manager the one
-- Cancel (order.cancel, cancel_order) and left "Sales asking for a cancel"
-- not built: the decision-rights row says Sales proposes, and today they ring
-- the Manager. Now the ask is a row, and every step of it pushes the one who
-- waits:
--
--   cancel_asks          one row per ask: the order, why (the canvas's four:
--                        changed their mind, entered twice, wrong items or
--                        how many, something else), a note, what the order
--                        came to and its stage when asked, who asked; then
--                        the answer (accepted, declined, withdrawn), who
--                        and when. One open ask per order. Members read it
--                        (not the yard: 0159, 0179); nobody writes it but
--                        the functions below.
--
--   ask_cancel(shop, order, why, note)
--       cancel.ask (new; Sales). Only on your own order (payload.takenBy),
--       before it is invoiced or delivered, and not called off already.
--       Asked again while the first waits: the open ask stands ('again').
--       Pushes the Manager (order.cancel.ask, to order.cancel).
--
--   withdraw_cancel_ask(id)
--       The asker takes it back while it waits. Again: nothing more.
--
--   answer_cancel_ask(id, yes, note, choice, account)
--       order.cancel (the Manager). Yes: the order is cancelled through
--       0177's cancel_order -- every refusal of its own (invoiced, goods
--       that came in, a live trip, money with no choice), the yard and the
--       salesperson pushed (order.cancelled), the owner's log from the void
--       guard -- and the ask closes with it. No: the ask is declined with
--       the Manager's words, logged (decision_log, order.cancel), and the
--       asker pushed (order.cancel.ask.decided).
--
--   And the ask follows the order: an order called off another way (the
--   console's Cancel, the Manager app's void of a copy) closes its open ask
--   as accepted, and the asker is told when it was not cancel_order that
--   did it (that one tells them itself); an order invoiced first closes it
--   as declined ("ask for a void"), and the asker is told.
--
-- Applied by hand, after 0177 (cancel_order) and 0180. Safe to run twice.
--
-- CHECK AFTERWARDS:
--   select role, task from role_tasks where task = 'cancel.ask';
--   select to_regclass('public.cancel_asks');
--   select tgname from pg_trigger where tgname in ('cancel_asks_ow_push', 'saved_quotes_ow_cancel_asks');
--   select status, count(*) from cancel_asks group by 1;
--
-- ROLLBACK:
--   drop trigger if exists saved_quotes_ow_cancel_asks on saved_quotes;
--   drop function if exists saved_quotes_ow_cancel_asks();
--   drop function if exists answer_cancel_ask(uuid, boolean, text, text, text);
--   drop function if exists withdraw_cancel_ask(uuid);
--   drop function if exists ask_cancel(uuid, bigint, text, text);
--   drop table if exists cancel_asks;   -- drops its push trigger with it
--   drop function if exists cancel_asks_ow_push();
--   delete from role_tasks where task = 'cancel.ask';
-- ---------------------------------------------------------------------

insert into role_tasks (role, task) values ('sales', 'cancel.ask') on conflict do nothing;

-- ---------------------------------------------------------------------
-- 1. The asks.
create table if not exists cancel_asks (
  id uuid primary key default gen_random_uuid(),
  shop_id uuid not null references shops(id) on delete cascade,
  quote_id bigint not null,
  customer_id text,
  why text not null,
  note text,
  amount numeric not null default 0,
  stage text,
  asked_by uuid not null default auth.uid(),
  asked_by_name text,
  status text not null default 'sent' check (status in ('sent', 'accepted', 'declined', 'withdrawn')),
  answer text,
  decided_by uuid,
  decided_at timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists cancel_asks_shop_idx on cancel_asks (shop_id, created_at desc);
create unique index if not exists cancel_asks_one_open on cancel_asks (shop_id, quote_id) where status = 'sent';
alter table cancel_asks enable row level security;

-- Members read them, but not the yard (a Store or yard-worker login reads no
-- books: 0159, 0179). No insert, update or delete policy: the functions write.
drop policy if exists "members read cancel asks" on cancel_asks;
create policy "members read cancel asks" on cancel_asks
  for select using (is_shop_member(shop_id)
    and not exists (select 1 from shop_members m where m.shop_id = cancel_asks.shop_id and m.user_id = auth.uid() and m.role in ('store', 'staff')));

-- ---------------------------------------------------------------------
-- 2. Asking.
create or replace function ask_cancel(p_shop_id uuid, p_order bigint, p_why text, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  why text := left(nullif(btrim(coalesce(p_why, '')), ''), 200);
  q saved_quotes%rowtype;
  a cancel_asks%rowtype;
  lbl text;
begin
  if uid is null or not is_shop_member(p_shop_id) then
    raise exception 'Sign in to this shop first.' using errcode = '42501';
  end if;
  if not has_task(p_shop_id, 'cancel.ask') then
    raise exception 'Asking for a cancel is Sales'' (cancel.ask).' using errcode = '42501';
  end if;
  if why is null then raise exception 'Say why it should be cancelled.' using errcode = '22023'; end if;
  select * into q from saved_quotes where shop_id = p_shop_id and id = p_order for update;
  if not found then raise exception 'This order is no longer in the books.' using errcode = 'P0002'; end if;
  lbl := '#' || lpad(q.id::text, 4, '0');
  if ow_uuid(q.payload ->> 'takenBy') is distinct from uid then
    raise exception 'Only the one who took % asks to cancel it.', lbl using errcode = '42501';
  end if;
  if coalesce(q.voided, false) or q.status = 'cancelled' then raise exception '% is called off already.', lbl using errcode = '22023'; end if;
  if coalesce(q.invoiced, false) then raise exception '% is invoiced: ask for a void instead.', lbl using errcode = '22023'; end if;
  if q.status = 'completed' then raise exception '% was delivered: ask for a void once it is invoiced.', lbl using errcode = '22023'; end if;

  -- Asked already: the ask that waits stands.
  select * into a from cancel_asks where shop_id = p_shop_id and quote_id = q.id and status = 'sent';
  if found then
    return jsonb_build_object('ok', true, 'id', a.id, 'orderId', q.id, 'status', a.status, 'amount', a.amount, 'at', a.created_at, 'again', true);
  end if;
  insert into cancel_asks (shop_id, quote_id, customer_id, why, note, amount, stage, asked_by, asked_by_name)
       values (p_shop_id, q.id, nullif(q.payload ->> 'customerId', ''), why, left(nullif(btrim(coalesce(p_note, '')), ''), 500),
               greatest(0, round(ow_order_total(p_shop_id, q.payload, true))), q.status, uid,
               coalesce((select nullif(btrim(m.display_name), '') from shop_members m where m.shop_id = p_shop_id and m.user_id = uid limit 1),
                        (select nullif(btrim(st.name), '') from staff st where st.shop_id = p_shop_id and st.user_id = uid and btrim(st.name) !~ '@' limit 1)))
  returning * into a;
  return jsonb_build_object('ok', true, 'id', a.id, 'orderId', q.id, 'status', a.status, 'amount', a.amount, 'at', a.created_at, 'again', false);
end $$;
revoke all on function ask_cancel(uuid, bigint, text, text) from public, anon;
grant execute on function ask_cancel(uuid, bigint, text, text) to authenticated;

-- ---------------------------------------------------------------------
-- 3. Taking it back.
create or replace function withdraw_cancel_ask(p_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  a cancel_asks%rowtype;
begin
  select * into a from cancel_asks where id = p_id for update;
  if not found or a.asked_by is distinct from auth.uid() then
    raise exception 'That ask is not yours.' using errcode = '42501';
  end if;
  if a.status = 'withdrawn' then
    return jsonb_build_object('ok', true, 'id', a.id, 'status', a.status, 'again', true);
  end if;
  if a.status <> 'sent' then
    raise exception 'That ask is % already.', a.status using errcode = '22023';
  end if;
  update cancel_asks set status = 'withdrawn', decided_at = now() where id = p_id;
  return jsonb_build_object('ok', true, 'id', a.id, 'status', 'withdrawn', 'again', false);
end $$;
revoke all on function withdraw_cancel_ask(uuid) from public, anon;
grant execute on function withdraw_cancel_ask(uuid) to authenticated;

-- ---------------------------------------------------------------------
-- 4. The Manager's answer: yes through cancel_order, or no with words.
create or replace function answer_cancel_ask(p_id uuid, p_yes boolean, p_note text default null, p_choice text default null, p_account text default 'cash')
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  a cancel_asks%rowtype;
  v_note text := left(nullif(btrim(coalesce(p_note, '')), ''), 300);
  res jsonb;
  client text;
  lbl text;
begin
  if p_yes is null then raise exception 'Say yes or no.' using errcode = '22023'; end if;
  select * into a from cancel_asks where id = p_id for update;
  if not found then raise exception 'That ask is gone.' using errcode = 'P0002'; end if;
  if not has_task(a.shop_id, 'order.cancel') then
    raise exception 'Deciding a cancel is the Manager''s (order.cancel).' using errcode = '42501';
  end if;
  if a.status <> 'sent' then raise exception 'That ask is % already.', a.status using errcode = '22023'; end if;
  lbl := '#' || lpad(a.quote_id::text, 4, '0');

  if p_yes then
    -- 0177's one Cancel, with every refusal of its own; the order's void closes the ask (step 5).
    res := cancel_order(a.shop_id, a.quote_id, a.why || coalesce(' · ' || v_note, ''), p_choice, p_account);
    update cancel_asks set status = 'accepted', answer = v_note, decided_by = auth.uid(), decided_at = coalesce(decided_at, now()) where id = p_id;
    return jsonb_build_object('ok', true, 'id', a.id, 'orderId', a.quote_id, 'status', 'accepted', 'order', res);
  end if;

  update cancel_asks set status = 'declined', answer = v_note, decided_by = auth.uid(), decided_at = now() where id = p_id;
  select coalesce(nullif(btrim(coalesce(q.client_name, '')), ''), 'an order') into client
    from saved_quotes q where q.shop_id = a.shop_id and q.id = a.quote_id;
  perform manager_log_decision(a.shop_id, 'order.cancel',
    'Kept order ' || lbl || coalesce(' for ' || client, '') || ': declined ' || coalesce(nullif(a.asked_by_name, ''), 'a salesperson') || '''s ask to cancel it'
      || coalesce(' — ' || v_note, ''),
    a.amount, jsonb_build_object('table', 'cancel_asks', 'id', a.id, 'quote_id', a.quote_id),
    jsonb_build_object('status', 'sent', 'why', a.why), jsonb_build_object('status', 'declined', 'answer', v_note));
  return jsonb_build_object('ok', true, 'id', a.id, 'orderId', a.quote_id, 'status', 'declined');
end $$;
revoke all on function answer_cancel_ask(uuid, boolean, text, text, text) from public, anon;
grant execute on function answer_cancel_ask(uuid, boolean, text, text, text) to authenticated;

-- ---------------------------------------------------------------------
-- 5. The ask follows the order: called off closes it as accepted; invoiced first, as declined.
create or replace function saved_quotes_ow_cancel_asks() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  begin
    if coalesce(new.voided, false) and not coalesce(old.voided, false) then
      update cancel_asks set status = 'accepted', decided_by = auth.uid(), decided_at = now()
       where shop_id = new.shop_id and quote_id = new.id and status = 'sent';
    elsif coalesce(new.invoiced, false) and not coalesce(old.invoiced, false) then
      update cancel_asks set status = 'declined', decided_by = auth.uid(), decided_at = now(),
             answer = 'Invoiced before it was cancelled: ask for a void.'
       where shop_id = new.shop_id and quote_id = new.id and status = 'sent';
    end if;
  exception when others then
    raise notice 'cancel ask (order %): % (%)', new.id, sqlerrm, sqlstate;
  end;
  return null;
end $$;
drop trigger if exists saved_quotes_ow_cancel_asks on saved_quotes;
create trigger saved_quotes_ow_cancel_asks after update of voided, invoiced on saved_quotes
  for each row when (new.voided is distinct from old.voided or new.invoiced is distinct from old.invoiced)
  execute function saved_quotes_ow_cancel_asks();

-- ---------------------------------------------------------------------
-- 6. Pushes: the ask to the Manager; a no (or a void by another way) to the asker.
create or replace function cancel_asks_ow_push() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  client text;
  q_status text;
  q_invoiced boolean;
  lbl text := '#' || lpad(new.quote_id::text, 4, '0');
  who text;
  ref jsonb := jsonb_build_object('table', 'cancel_asks', 'id', new.id, 'quote', new.quote_id);
begin
  begin
    select coalesce(nullif(btrim(coalesce(q.client_name, '')), ''), nullif(btrim(coalesce(q.payload -> 'client' ->> 'name', '')), '')), q.status, coalesce(q.invoiced, false)
      into client, q_status, q_invoiced from saved_quotes q where q.shop_id = new.shop_id and q.id = new.quote_id;
    if tg_op = 'INSERT' and new.status = 'sent' then
      perform ow_push(new.shop_id, 'order.cancel.ask', 'Cancel asked',
        coalesce(nullif(split_part(btrim(coalesce(new.asked_by_name, '')), ' ', 1), ''), 'Sales') || ' asks to cancel ' || lbl
          || coalesce(' · ' || client, '') || ' · ' || ow_money(new.amount) || ' — ' || new.why,
        null, 'order.cancel', null, ref, 'cancelask:' || new.id);
    elsif tg_op = 'UPDATE' and old.status = 'sent' and (new.status = 'declined' or (new.status = 'accepted' and q_status is distinct from 'cancelled')) then
      -- The person's own name (0164's display name, else their staff name), never a role's stand-in.
      who := coalesce((select nullif(split_part(btrim(m.display_name), ' ', 1), '') from shop_members m where m.shop_id = new.shop_id and m.user_id = new.decided_by limit 1),
                      ow_first_name(new.shop_id, new.decided_by), 'The Manager');
      perform ow_push(new.shop_id, 'order.cancel.ask.decided',
        case when new.status = 'declined' then 'Not cancelled' else 'Called off' end,
        lbl || coalesce(' · ' || client, '') || ' — '
          || case when new.status = 'accepted' then who || ' voided it.'
                  when q_invoiced then 'invoiced before it was cancelled: ask for a void.'
                  else who || ' kept it' || coalesce(': ' || new.answer, '.') end,
        new.asked_by, null, null, ref, 'cancelaskdone:' || new.id);
    end if;
  exception when others then
    raise notice 'push (cancel ask): % (%)', sqlerrm, sqlstate;
  end;
  return null;
end $$;
drop trigger if exists cancel_asks_ow_push on cancel_asks;
create trigger cancel_asks_ow_push after insert or update on cancel_asks
  for each row execute function cancel_asks_ow_push();

commit;

-- =====================================================================
-- STEP 4  CHECK AFTERWARDS (read-only): every row says ok
-- =====================================================================
select m, case when ok then 'ok' else 'MISSING' end from (values
  ('0179 a yard worker keeps out of the books', (to_regprocedure('ow_yard_worker(uuid)') is not null
         and (select count(distinct polrelid) from pg_policy where polname = 'not a yard worker') >= 21
         and (select count(*) from role_tasks where role = 'staff' and task in ('order.pick', 'order.load', 'order.deliver')) = 3)
                                              and (select md5(translate(p.prosrc, chr(32) || chr(9) || chr(13) || chr(10), '')) from pg_proc p where p.oid = to_regprocedure('ow_yard_worker(uuid)')) = 'c05acf91e9c58923c977f185402ba489'),
  ('0180 place_order',                          (to_regprocedure('place_order(uuid, jsonb, text)') is not null and to_regclass('public.saved_quotes_place_key_idx') is not null)
                                              and (select md5(translate(p.prosrc, chr(32) || chr(9) || chr(13) || chr(10), '')) from pg_proc p where p.oid = to_regprocedure('place_order(uuid, jsonb, text)')) = '50c999404bb98a09e557b7f6440347d4'),
  ('0181 Sales asks to cancel',                 (to_regclass('public.cancel_asks') is not null and to_regprocedure('ask_cancel(uuid, bigint, text, text)') is not null
         and to_regprocedure('withdraw_cancel_ask(uuid)') is not null and to_regprocedure('answer_cancel_ask(uuid, boolean, text, text, text)') is not null
         and exists (select 1 from pg_trigger where tgname = 'saved_quotes_ow_cancel_asks') and exists (select 1 from pg_trigger where tgname = 'cancel_asks_ow_push')
         and exists (select 1 from role_tasks where role = 'sales' and task = 'cancel.ask'))
                                              and (select md5(translate(p.prosrc, chr(32) || chr(9) || chr(13) || chr(10), '')) from pg_proc p where p.oid = to_regprocedure('ask_cancel(uuid, bigint, text, text)')) = '5dccc4f68e8dad6a8d620d2ddd4ea706'
                                              and (select md5(translate(p.prosrc, chr(32) || chr(9) || chr(13) || chr(10), '')) from pg_proc p where p.oid = to_regprocedure('withdraw_cancel_ask(uuid)')) = '484fbcab18da389e42af85a8f9db37e9'
                                              and (select md5(translate(p.prosrc, chr(32) || chr(9) || chr(13) || chr(10), '')) from pg_proc p where p.oid = to_regprocedure('answer_cancel_ask(uuid, boolean, text, text, text)')) = '89f77eaa45a9091057458698e419120c'
                                              and (select md5(translate(p.prosrc, chr(32) || chr(9) || chr(13) || chr(10), '')) from pg_proc p where p.oid = to_regprocedure('saved_quotes_ow_cancel_asks()')) = '52be44881c46b2c59166f41ec6e021f2'
                                              and (select md5(translate(p.prosrc, chr(32) || chr(9) || chr(13) || chr(10), '')) from pg_proc p where p.oid = to_regprocedure('cancel_asks_ow_push()')) = 'd2e7db961ed9c5aa50ee48ba06cd53ab')
) as t(m, ok);
